c1754.try_sql:
-- VALUES in WITH, in a multi-row INSERT and as the source of a MERGE
WITH v (n) AS (VALUES (1), (2), (3))
SELECT SUM(n) AS total FROM v;
INSERT INTO promotions (promo_id, promo_name, discount_pct) VALUES (901, 'Spring', 5), (902, 'Summer', 10);
MERGE INTO promotions p
USING (VALUES (902, 'Summer', 15), (903, 'Autumn', 20)) v (id, name, pct)
ON (p.promo_id = v.id)
WHEN MATCHED THEN UPDATE SET p.discount_pct = v.pct
WHEN NOT MATCHED THEN INSERT (promo_id, promo_name, discount_pct) VALUES (v.id, v.name, v.pct);
SELECT * FROM promotions ORDER BY promo_id;

