c1772.try_sql:
-- A domain with CHECK and DISPLAY: a bad email raises ORA-11534, DOMAIN_DISPLAY shows lowercase
CREATE DOMAIN lab_c1772_email AS VARCHAR2(100)
  CONSTRAINT lab_c1772_email_ck CHECK (REGEXP_LIKE(lab_c1772_email, '@'))
  DISPLAY LOWER(lab_c1772_email);
CREATE TABLE lab_c1772_t (id NUMBER, email lab_c1772_email);
INSERT INTO lab_c1772_t VALUES (1, 'Ann@Example.COM');
INSERT INTO lab_c1772_t VALUES (2, 'no-at-sign');
SELECT id, email, DOMAIN_DISPLAY(email) AS disp, DOMAIN_NAME(email) AS dn FROM lab_c1772_t;

c1774.try_sql:
-- DROP DOMAIN with a dependent column: ORA-11502; FORCE detaches the domain, the type and data stay
CREATE DOMAIN lab_c1774_d AS NUMBER(3) CONSTRAINT lab_c1774_d_ck CHECK (lab_c1774_d > 0);
CREATE TABLE lab_c1774_t (n lab_c1774_d);
INSERT INTO lab_c1774_t VALUES (5);
DROP DOMAIN lab_c1774_d;
DROP DOMAIN lab_c1774_d FORCE;
SELECT c.column_name, c.data_type, c.data_precision, c.domain_name, (SELECT MAX(n) FROM lab_c1774_t) AS dane
FROM   user_tab_columns c WHERE c.table_name = 'LAB_C1774_T';

